{"file_path":"src/policies.js","content":"/**
 * The rate limiting policies. Every policy keeps one independent state per
 * key, and answers the same three questions: advance to a tick, allow a
 * request, record a request.
 *
 * Token counts are kept as exact rationals with the bucket's period as the
 * denominator, so a partial period is never rounded away.
 */

export class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.full = capacity * per
    this.states = new Map()
  }

  /** Adds the tokens the elapsed ticks earned, never passing the capacity. */
  advance(key, tick) {
    const state = this.states.get(key)
    if (state === undefined) {
      this.states.set(key, { tokens: this.full, last: tick })
      return
    }
    const elapsed = tick - state.last
    if (elapsed > 0n) {
      const tokens = state.tokens + this.refill * elapsed
      state.tokens = tokens > this.full ? this.full : tokens
    }
    state.last = tick
  }

  /** Whether the bucket holds at least one whole token. */
  allows(key) {
    return this.states.get(key).tokens >= this.per
  }

  /** Spends exactly one whole token. */
  record(key) {
    const state = this.states.get(key)
    state.tokens -= this.per
  }
}

export class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  /** Forgets every remembered tick at or before the tick minus the span. */
  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    const cutoff = tick - this.span
    let kept = 0
    while (kept < ticks.length && ticks[kept] <= cutoff) kept += 1
    if (kept > 0) ticks.splice(0, kept)
  }

  /** Whether fewer than the limit of requests remain remembered. */
  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  /** Remembers this tick. */
  record(key) {
    const ticks = this.states.get(key)
    ticks.push(ticks.lastTick)
  }
}
"}

