 * The limiter file parser. It turns the text of a limiter file into the
 * declared policies, the routes and the event log, and reports the first
 * failure it meets as a ParseError carrying the offending line number.
 */

import { Bucket, Window } from './policies.js'

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INTEGER = /^(?:0|[1-9][0-9]*)$/

/** An unsigned decimal integer, written without a sign and without a leading zero. */
function integer(line, field, text, least) {
  if (!INTEGER.test(text)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(text)
  if (value < BigInt(least)) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return value
}

/** Splits the input into its significant lines, keeping each one's number. */
function lines(text) {
  const raw = text.split('\n')
  if (raw.length > 0 && text.endsWith('\n')) raw.pop()
  const out = []
  for (let index = 0; index < raw.length; index += 1) {
    const trimmed = raw[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    out.push({ number: index + 1, words: trimmed.split(/\s+/) })
  }
  return out
}

export function parse(text) {
  const policies = new Map()
  const routes = []
  const prefixes = new Set()
  const events = []

  for (const { number, words } of lines(text)) {
    const directive = words[0]
    if (directive === 'bucket') {
      if (words.length !== 5) {
        throw new ParseError(number, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const name = words[1]
      if (!NAME.test(name)) throw new ParseError(number, `invalid policy name ${name}`)
      const capacity = integer(number, 'capacity', words[2], 1)
      const refill = integer(number, 'refill', words[3], 0)
      const per = integer(number, 'per', words[4], 1)
      declare(number, policies, events, name, new Bucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) {
        throw new ParseError(number, 'expected window <name> <limit> <span>')
      }
      const name = words[1]
      if (!NAME.test(name)) throw new ParseError(number, `invalid policy name ${name}`)
      const limit = integer(number, 'limit', words[2], 0)
      const span = integer(number, 'span', words[3], 1)
      declare(number, policies, events, name, new Window(name, limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) {
        throw new ParseError(number, 'expected route <prefix> <policy>...')
      }
      const prefix = words[1]
      if (!NAME.test(prefix)) throw new ParseError(number, `invalid route prefix ${prefix}`)
      const named = words.slice(2)
      for (const name of named) {
        if (!NAME.test(name)) throw new ParseError(number, `invalid policy name ${name}`)
      }
      if (events.length > 0) {
        throw new ParseError(number, 'declarations must come before the first event')
      }
      for (const name of named) {
        if (!policies.has(name)) throw new ParseError(number, `unknown policy ${name}`)
      }
      if (prefixes.has(prefix)) throw new ParseError(number, `prefix ${prefix} is routed twice`)
      prefixes.add(prefix)
      routes.push({ prefix, policies: named.map((name) => policies.get(name)) })
    } else if (directive === 'event') {
      if (words.length !== 3) throw new ParseError(number, 'expected event <tick> <key>')
      const tick = integer(number, 'tick', words[1], 0)
      const key = words[2]
      if (!NAME.test(key)) throw new ParseError(number, `invalid key ${key}`)
      const previous = events.length > 0 ? events[events.length - 1].tick : null
      if (previous !== null && tick < previous) {
        throw new ParseError(number, `tick ${tick} is before tick ${previous}`)
      }
      events.push({ tick, key })
    } else {
      throw new ParseError(number, `unknown directive ${directive}`)
    }
  }

  // The longest matching prefix wins, so the longest routes are tried first.
  routes.sort((a, b) => b.prefix.length - a.prefix.length)
  return { routes, events }
}

function declare(number, policies, events, name, policy) {
  if (events.length > 0) {
    throw new ParseError(number, 'declarations must come before the first event')
  }
  if (policies.has(name)) throw new ParseError(number, `policy ${name} is declared twice`)
  policies.set(name, policy)
}
"}

