{"file_path":"src/simulate.js","content":"/**
 * The simulation and its two reports. Every event is routed to at most one
 * route, whose policies all advance, are all asked, and only record when all
 * of them allowed the request.
 */

/** The route whose prefix matches and is longest among those that match. */
function routeFor(routes, key) {
  for (const route of routes) {
    if (key.startsWith(route.prefix)) return route
  }
  return null
}

/** Verdicts every event in log order, naming the policy that refused. */
export function simulate({ routes, events }) {
  const verdicts = []
  for (const { tick, key } of events) {
    const route = routeFor(routes, key)
    if (route === null) {
      verdicts.push({ tick, key, denier: null })
      continue
    }
    for (const policy of route.policies) policy.advance(key, tick)
    let denier = null
    for (const policy of route.policies) {
      if (!policy.allows(key)) {
        denier = policy
        break
      }
    }
    if (denier === null) {
      for (const policy of route.policies) policy.record(key, tick)
    }
    verdicts.push({ tick, key, denier })
  }
  return verdicts
}

export function replay(verdicts) {
  let out = ''
  for (const { tick, key, denier } of verdicts) {
    out += denier === null ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${denier.name}\n`
  }
  return out
}

export function summary(verdicts) {
  const counts = new Map()
  let allowed = 0
  let denied = 0
  for (const { key, denier } of verdicts) {
    let count = counts.get(key)
    if (count === undefined) {
      count = { allowed: 0, denied: 0 }
      counts.set(key, count)
    }
    if (denier === null) {
      count.allowed += 1
      allowed += 1
    } else {
      count.denied += 1
      denied += 1
    }
  }
  const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let out = ''
  for (const key of keys) {
    const count = counts.get(key)
    out += `${key} allowed=${count.allowed} denied=${count.denied}\n`
  }
  return `${out}total allowed=${allowed} denied=${denied}\n`
}
"}

