/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parse } from './parse.js'
import { replay, simulate, summary } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'replay' && mode !== 'summary') fail('usage: cli.js replay|summary')

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let out
  try {
    const verdicts = simulate(parse(input))
    out = mode === 'replay' ? replay(verdicts) : summary(verdicts)
  } catch (error) {
    if (error instanceof ParseError) fail(error.message)
    throw error
  }
  process.stdout.write(out)
}

main(process.argv.slice(2))
"}

